import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { startServer, removeDataDir, type StartedServer } from './testing/server.ts';

let server: StartedServer;
let pageScript: string;

before(async () => {
  server = await startServer();
  const res = await fetch(`${server.origin}/`);
  const html = await res.text();
  const start = html.indexOf('<script>');
  const end = html.lastIndexOf('</script>');
  pageScript = html.slice(start + '<script>'.length, end);
});
after(async () => { await server.stop(); removeDataDir(server); });

interface El {
  tagName: string; hidden: boolean; value: string; dateTime: string; children: El[];
  text: string | null; textContent: string;
  listeners: Record<string, Array<(e: unknown) => unknown>>;
  append(...n: El[]): void; replaceChildren(...n: El[]): void;
  addEventListener(t: string, fn: (e: unknown) => unknown): void; reset(): void;
}
function makeElement(tag: string): El {
  const node: any = {
    tagName: tag.toUpperCase(), hidden: false, value: '', dateTime: '', children: [], text: null,
    listeners: {},
    append(...n: El[]) { this.children.push(...n); },
    replaceChildren(...n: El[]) { this.children = [...n]; },
    addEventListener(t: string, fn: (e: unknown) => unknown) { (this.listeners[t] ??= []).push(fn); },
    reset() {},
  };
  Object.defineProperty(node, 'textContent', {
    get() { return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join(''); },
    set(v: unknown) { this.text = String(v); },
  });
  return node as El;
}
interface Gate { promise: Promise<unknown>; resolve: (v?: unknown) => void; reject: (e: Error) => void; }
function gate(): Gate {
  let resolve!: (v?: unknown) => void; let reject!: (e: Error) => void;
  const promise = new Promise<unknown>((res, rej) => { resolve = res as any; reject = rej; });
  return { promise, resolve, reject };
}
function jsonResponse(status: number, body: unknown): any {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}
const flush = (): Promise<void> => new Promise((r) => setTimeout(r, 0));
let seq = 0;
function makeIdea(partial: Record<string, unknown> = {}): Record<string, unknown> {
  seq += 1;
  return { id: `id-${seq}`, title: `标题${seq}`, description: `说明${seq}`, scenario: '', createdAt: '2026-01-01T00:00:00.000Z', ...partial };
}

class Harness {
  els: Record<string, El> = {};
  gets: Gate[] = []; posts: Gate[] = [];
  constructor(script: string) {
    const byId = new Map<string, El>();
    const register = (id: string, tag: string, hidden = false): El => {
      const n = makeElement(tag); n.hidden = hidden; byId.set(id, n); this.els[id] = n; return n;
    };
    const form = register('idea-form', 'form');
    const titleInput = register('f-title', 'input');
    const descInput = register('f-desc', 'textarea');
    register('f-scenario', 'textarea');
    register('error', 'p', true);
    register('success', 'p', true);
    register('empty', 'p', true);
    register('ideas', 'div');
    form.reset = () => { titleInput.value = ''; descInput.value = ''; (this.els['f-scenario']).value = ''; };
    const fetchMock = (_url: unknown, init?: { method?: string }) => {
      const pending = gate();
      if ((init?.method ?? 'GET') === 'POST') this.posts.push(pending); else this.gets.push(pending);
      return pending.promise;
    };
    vm.runInContext(script, vm.createContext({ console, document: {
      getElementById: (id: string) => byId.get(id)!,
      createElement: (t: string) => makeElement(t),
    }, fetch: fetchMock }), { filename: 'p.js' });
  }
  setForm(v: { title?: string; description?: string; scenario?: string }) {
    if (v.title !== undefined) this.els['f-title'].value = v.title;
    if (v.description !== undefined) this.els['f-desc'].value = v.description;
    if (v.scenario !== undefined) this.els['f-scenario'].value = v.scenario;
  }
  submit(): Promise<unknown> {
    return this.els['idea-form'].listeners.submit[0]({ preventDefault() {} });
  }
  titles(): string[] {
    return this.els.ideas.children.filter((n) => n.tagName === 'ARTICLE')
      .map((a) => a.children.find((n) => n.tagName === 'H3')!.textContent);
  }
}
const SUCCESS_TEXT = '提交成功，你的意见已保存。';
const NETWORK_ERROR_TEXT = '网络错误，提交未成功，请重试。';

test('场景1：先提交迟到网络失败，后提交已确认保存 → 仍显示后一次成功；先提交未保存不入列表', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '先提交', description: '说明一' });
  const first = h.submit();
  h.setForm({ title: '后提交', description: '说明二' });
  const second = h.submit();
  assert.equal(h.posts.length, 2);

  // 后一次先成功
  h.posts[1].resolve(jsonResponse(201, { idea: makeIdea({ id: 'b', title: '后提交', description: '说明二' }) }));
  await second; await flush();
  assert.equal(h.els.success.hidden, false);
  assert.equal(h.els.success.textContent, SUCCESS_TEXT);
  assert.equal(h.els.error.hidden, true);

  // 等待期间不应有提示
  // 较早的请求迟到失败
  h.posts[0].reject(new TypeError('Failed to fetch'));
  await first; await flush();

  assert.equal(h.els.success.hidden, false, '成功提示保留');
  assert.equal(h.els.success.textContent, SUCCESS_TEXT);
  assert.equal(h.els.error.hidden, true, '迟到失败不显示');
  assert.deepEqual(h.titles(), ['后提交']);
});

test('场景2：后提交被服务拒绝，先提交迟到确认保存 → 保留后一次失败；先提交仍进列表', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '先提交', description: '说明一' });
  const first = h.submit();
  h.setForm({ title: '后提交', description: '说明二' });
  const second = h.submit();

  // 后一次先被拒绝
  h.posts[1].resolve(jsonResponse(400, { error: '服务拒绝原因' }));
  await second; await flush();
  assert.equal(h.els.error.hidden, false);
  assert.equal(h.els.error.textContent, '提交失败：服务拒绝原因');
  assert.equal(h.els.success.hidden, true);

  // 较早的请求迟到成功
  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '先提交', description: '说明一' }) }));
  await first; await flush();

  assert.equal(h.els.error.hidden, false, '失败提示保留');
  assert.equal(h.els.error.textContent, '提交失败：服务拒绝原因');
  assert.equal(h.els.success.hidden, true, '迟到成功不显示成功提示');
  // 但先提交确认保存的意见仍进入列表
  assert.deepEqual(h.titles(), ['先提交']);
});

test('场景3：后一次点击被字段校验拦下，较早请求迟到返回 → 保留字段错误，且不被成功/失败掩盖', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '先提交', description: '说明一' });
  const first = h.submit();

  // 用户改出非法内容并再次点击（被表单直接拦下）
  h.setForm({ title: '   ', description: '说明二' });
  await h.submit();
  assert.equal(h.posts.length, 1, '校验拦截不发请求');
  assert.equal(h.els.error.hidden, false);
  assert.equal(h.els.error.textContent, '标题不能为空。');
  assert.equal(h.els.success.hidden, true);

  // 较早请求迟到成功
  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '先提交' }) }));
  await first; await flush();
  assert.equal(h.els.error.hidden, false, '字段错误保留');
  assert.equal(h.els.error.textContent, '标题不能为空。');
  assert.equal(h.els.success.hidden, true, '迟到成功不显示');
  assert.deepEqual(h.titles(), ['先提交'], '迟到成功仍进列表');

  // 另起一个 harness 验证：较早请求迟到失败也不掩盖字段错误
  const h2 = new Harness(pageScript);
  h2.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();
  h2.setForm({ title: '先提交', description: '说明一' });
  const first2 = h2.submit();
  h2.setForm({ title: '有效', description: '   ' });
  await h2.submit();
  assert.equal(h2.els.error.textContent, '详细说明不能为空。');
  h2.posts[0].reject(new TypeError('Failed to fetch'));
  await first2; await flush();
  assert.equal(h2.els.error.hidden, false);
  assert.equal(h2.els.error.textContent, '详细说明不能为空。');
  assert.equal(h2.els.success.hidden, true);
  assert.deepEqual(h2.titles(), []);
});

test('场景4：新提交在途时旧请求迟到成功，不抢先显示成功；最新请求结果到达后只显示它', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '先提交', description: '说明一' });
  const first = h.submit();
  h.setForm({ title: '后提交', description: '说明二' });
  const second = h.submit();

  // 较早请求先返回成功（此刻最近一次点击仍是后提交，等待中）
  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '先提交' }) }));
  await first; await flush();
  assert.equal(h.els.success.hidden, true, '等待后一次时不显示先提交的成功');
  assert.equal(h.els.error.hidden, true);
  assert.deepEqual(h.titles(), ['先提交'], '保存事实仍入列表');

  // 后提交网络失败
  h.posts[1].reject(new TypeError('Failed to fetch'));
  await second; await flush();
  assert.equal(h.els.error.hidden, false);
  assert.equal(h.els.error.textContent, NETWORK_ERROR_TEXT);
  assert.equal(h.els.success.hidden, true);
  assert.deepEqual(h.titles(), ['先提交']);
});

test('场景5：成功后再次提交失败，更早无在途；以及失败后再提交成功的常规归属', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '第一条', description: '说明' });
  const p1 = h.submit();
  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '第一条' }) }));
  await p1; await flush();
  assert.equal(h.els.success.hidden, false);

  h.setForm({ title: '第二条', description: '说明' });
  const p2 = h.submit();
  assert.equal(h.els.success.hidden, true, '新提交发起后旧成功提示先清除');
  assert.equal(h.els.error.hidden, true);
  h.posts[1].reject(new TypeError('Failed to fetch'));
  await p2; await flush();
  assert.equal(h.els.error.hidden, false);
  assert.equal(h.els.success.hidden, true);
  assert.deepEqual(h.titles(), ['第一条']);
});

