  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '先提交' }) }));
  await first; await flush();
  assert.equal(h.els.error.hidden, false, '字段错误保留');
  assert.equal(h.els.error.textContent, '标题不能为空。');
  assert.equal(h.els.success.hidden, true, '迟到成功不显示');
  assert.deepEqual(h.titles(), ['先提交'], '迟到成功仍进列表');

  // 另起一个 harness 验证：较早请求迟到失败也不掩盖字段错误
  const h2 = new Harness(pageScript);
  h2.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();
  h2.setForm({ title: '先提交', description: '说明一' });
  const first2 = h2.submit();
  h2.setForm({ title: '有效', description: '   ' });
  await h2.submit();
  assert.equal(h2.els.error.textContent, '详细说明不能为空。');
  h2.posts[0].reject(new TypeError('Failed to fetch'));
  await first2; await flush();
  assert.equal(h2.els.error.hidden, false);
  assert.equal(h2.els.error.textContent, '详细说明不能为空。');
  assert.equal(h2.els.success.hidden, true);
  assert.deepEqual(h2.titles(), []);
});

test('场景4：新提交在途时旧请求迟到成功，不抢先显示成功；最新请求结果到达后只显示它', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '先提交', description: '说明一' });
  const first = h.submit();
  h.setForm({ title: '后提交', description: '说明二' });
  const second = h.submit();

  // 较早请求先返回成功（此刻最近一次点击仍是后提交，等待中）
  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '先提交' }) }));
  await first; await flush();
  assert.equal(h.els.success.hidden, true, '等待后一次时不显示先提交的成功');
  assert.equal(h.els.error.hidden, true);
  assert.deepEqual(h.titles(), ['先提交'], '保存事实仍入列表');

  // 后提交网络失败
  h.posts[1].reject(new TypeError('Failed to fetch'));
  await second; await flush();
  assert.equal(h.els.error.hidden, false);
  assert.equal(h.els.error.textContent, NETWORK_ERROR_TEXT);
  assert.equal(h.els.success.hidden, true);
  assert.deepEqual(h.titles(), ['先提交']);
});

test('场景5：成功后再次提交失败，更早无在途；以及失败后再提交成功的常规归属', async () => {
  const h = new Harness(pageScript);
  h.gets[0].resolve(jsonResponse(200, { ideas: [] }));
  await flush();

  h.setForm({ title: '第一条', description: '说明' });
  const p1 = h.submit();
  h.posts[0].resolve(jsonResponse(201, { idea: makeIdea({ id: 'a', title: '第一条' }) }));
  await p1; await flush();
  assert.equal(h.els.success.hidden, false);

  h.setForm({ title: '第二条', description: '说明' });
  const p2 = h.submit();
  assert.equal(h.els.success.hidden, true, '新提交发起后旧成功提示先清除');
  assert.equal(h.els.error.hidden, true);
  h.posts[1].reject(new TypeError('Failed to fetch'));
  await p2; await flush();
  assert.equal(h.els.error.hidden, false);
  assert.equal(h.els.success.hidden, true);
  assert.deepEqual(h.titles(), ['第一条']);
});

